-- =====================================================================================
-- reconcile.sql - bring a Hust app DB (hust / hust_stage / hust_dev) up to the schema that
-- ever-hust origin/main packages/db/src/schema declares: indexes, UNIQUE constraints, FKs.
--
-- GENERATED by gen-sql.cjs from a drizzle-kit 0.31.9 push into an EMPTY PostgreSQL db, so
-- every name and definition below is exactly what drizzle declares.
--
-- Properties:
--   * idempotent   - safe to run any number of times; a second run changes nothing
--   * additive     - NO DROP of anything, NO data change (no INSERT/UPDATE/DELETE)
--   * per database - run once per DB, separately:
--       psql -X -v ON_ERROR_STOP=1 -d <db> -f reconcile.sql
--   * must NOT run inside a transaction (CREATE INDEX CONCURRENTLY): never use -1 /
--     --single-transaction, never wrap it in BEGIN.
--
-- Order: 0 guards -> 1 extensions -> 2 indexes (CONCURRENTLY) -> 3 UNIQUE constraints
--        -> 4 FKs as NOT VALID -> 5 VALIDATE FKs that have 0 orphans -> 6 summary
-- FKs with orphan rows are LEFT NOT VALID and reported; orphans are NEVER deleted.
-- A declared FK whose column already has an FK with a different definition is NOT added
-- (WARNING "fk CONFLICT"; verify.sql reports fks_mismatch) - that is an owner decision.
-- =====================================================================================
\set ON_ERROR_STOP 1
\set QUIET 1
\pset pager off
SET application_name = 'hust-schema-reconcile';
SET search_path = pg_catalog, public;
SET client_min_messages = notice;

-- ---------- 0. guards ----------------------------------------------------------------
-- (a failed guard raises an error, so psql exits non-zero under ON_ERROR_STOP)
DO $guard$
BEGIN
  IF pg_catalog.pg_is_in_recovery() THEN
    RAISE EXCEPTION 'ABORT: connected to a hot standby (replica). Run this on the PRIMARY.';
  END IF;
  IF current_database() NOT IN ('hust','hust_stage','hust_dev')
     AND coalesce(current_setting('hust.reconcile_allow_db', true), '') <> current_database() THEN
    RAISE EXCEPTION 'ABORT: database % is not hust / hust_stage / hust_dev', current_database();
  END IF;
  IF to_regclass('public.users') IS NULL OR to_regclass('public.jobs') IS NULL
     OR to_regclass('public.applications') IS NULL OR to_regclass('public.email_messages') IS NULL
     OR to_regclass('public.credit_transactions') IS NULL THEN
    RAISE EXCEPTION 'ABORT: % does not look like a Hust app DB (public.users/jobs/applications/email_messages/credit_transactions missing)', current_database();
  END IF;
END
$guard$;
SELECT current_database() AS db, current_user AS usr, pg_catalog.version() AS ver \gset
\echo '== reconcile start: db=' :db ' user=' :usr
\echo '==' :ver

-- ---------- 1. extensions ------------------------------------------------------------
-- None required: GIN on jsonb uses the core jsonb_ops opclass, to_tsvector('english', ...)
-- and gen_random_uuid() are core. pg_trgm is NOT used by the schema. Nothing to create.

-- ---------- 2. indexes (62 declared; CONCURRENTLY, outside any transaction) --------
-- A failed CONCURRENTLY build leaves an INVALID index that "IF NOT EXISTS" would silently
-- accept, so an INVALID leftover with a target name is rebuilt in place with
-- REINDEX INDEX CONCURRENTLY (no DROP). lock_timeout is long here on purpose: a lock
-- timeout in the middle of CREATE INDEX CONCURRENTLY is exactly what leaves an INVALID
-- index behind, and CONCURRENTLY never blocks the app's reads/writes while it waits.
SET lock_timeout = '5min';
SET statement_timeout = '30min';

-- accounts_user_id_idx
SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid = i.indexrelid WHERE c.relnamespace = 'public'::regnamespace AND c.relname = 'accounts_user_id_idx' AND i.indisvalid) AS idx_ok, EXISTS (SELECT 1 FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid = i.indexrelid WHERE c.relnamespace = 'public'::regnamespace AND c.relname = 'accounts_user_id_idx' AND NOT i.indisvalid) AS idx_invalid, false AS has_dups \gset
\if :idx_ok
  \echo 'index exists           accounts_user_id_idx'
\elif :has_dups
  \echo 'WARNING: SKIPPED unique index accounts_user_id_idx: duplicate (user_id) values exist in accounts - left for an owner decision'
\elif :idx_invalid
  \echo 'index INVALID -> REINDEX accounts_user_id_idx'
  REINDEX INDEX CONCURRENTLY "public"."accounts_user_id_idx";
\else
  \echo 'index CREATE           accounts_user_id_idx'
  CREATE INDEX CONCURRENTLY IF NOT EXISTS "accounts_user_id_idx" ON "public"."accounts" USING btree ("user_id");
\endif
